private static final class ImageTransferable implements Transferable {
    private final BufferedImage image;

    private ImageTransferable(BufferedImage image) {
        this.image = image;
    }

    @Override
    public DataFlavor[] getTransferDataFlavors() {
        return new DataFlavor[]{DataFlavor.imageFlavor};
    }

    @Override
    public boolean is_data_flavor_supported(DataFlavor flavor) {
        return DataFlavor.imageFlavor.equals(flavor);
    }

    @Override
    public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException, IOException {
        if (!is_data_flavor_supported(flavor)) {
            throw new UnsupportedFlavorException(flavor);
        }
        return image;
    }
}
